/**
 * integrations-shared.js — everything the Integrations hub and the per-provider
 * detail pages share: descriptors, walkthrough copy, status derivation, the
 * injected stylesheet, and every action (connect / disconnect / sync / the
 * sub-account pickers / the CallRail paste-key flow).
 *
 * Why one module: Google Ads and Google Analytics are the same integration in
 * two costumes, and the 0dcf1f4 drift bug (an error-surfacing fix landing on
 * one copy and missing the other) is what the descriptor design exists to
 * prevent. The hub renders navigation tiles only; ALL configuration lives on
 * the detail pages, driven by these descriptors.
 *
 * Actions take an optional `refresh` callback (the calling page's reload)
 * instead of assuming the hub's load() - the same handler works on either page.
 */

import AuthController from './AuthController.js';
import PubSub from 'pubsub-js';
import AppBroadcast from '../../../../shared/appBroadcast.js';
import { confirmDialog } from '../core/confirmDialog.js';

export const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ESC[c]);
export const toast = (message, type = 'info') => { try { PubSub.publish(AppBroadcast.UI_TOAST, { message, type }); } catch { /* no-op */ } };
export const apiBase = () => AuthController.getConfig?.().BASE_URL || '';
export const orgGuid = () => AuthController.getActiveOrg()?.guid || AuthController.getMemberships()[0]?.orgGuid || null;
export const canManage = () => AuthController.getCapabilities().includes('manage_magnets');

export const emptyState = (icon, msg) =>
  `<div class="m5t-empty"><span class="material-symbols-outlined" aria-hidden="true">${icon}</span><p>${msg}</p></div>`;

export const alertHTML = (msg, kind = '') =>
  `<div class="intg-alert ${kind}"><span class="material-symbols-outlined" aria-hidden="true">${kind === 'error' ? 'error' : 'info'}</span><span>${msg}</span></div>`;

// Shared busy latch across both pages (a click during an in-flight action is a no-op).
const busyLock = { busy: false };

// ── OAuth-return handoff (hub -> detail) ─────────────────────────────────────
// The server callback always lands on the hub (its redirect target is part of
// four OAuth app registrations - not worth changing). The hub toasts, strips
// the search string, parks the outcome here, and navigates to the provider's
// detail page, which picks it up to auto-open the right picker.
let pendingReturn = null;
export function setPendingReturn(v) { pendingReturn = v; }
export function takePendingReturn() { const v = pendingReturn; pendingReturn = null; return v; }

// ── walkthrough copy ─────────────────────────────────────────────────────────
// One sentence of "what this does" + numbered setup steps per provider. On the
// detail page these render as a real stepper with done-states; once healthy
// they collapse into a "Setup guide" disclosure.
import {
  WALKTHROUGHS, PROVIDERS, CATEGORIES, AUTOMATION_TILES, AUTOMATION_INTEGRATIONS, WIDE_MARKS,
} from './integrations-registry.js';

// Re-exported so every existing import site keeps working; the data itself
// lives in integrations-registry.js - the single source of truth that also
// generates the website /integrations/ page and the docs pages
// (scripts/export-integrations.mjs). New integration = one registry entry.
export { WALKTHROUGHS, PROVIDERS, CATEGORIES, AUTOMATION_TILES, AUTOMATION_INTEGRATIONS };

export const URL_TO_SLUG = Object.fromEntries(Object.values(PROVIDERS).map((p) => [p.urlSlug, p.slug]));

// ── status + shared render pieces ────────────────────────────────────────────
/** The provider mark: real brand SVG inside the tinted tile, Material glyph as
 * the onerror fallback (CallRail ships this way until its press-kit SVG lands). */
export function logoHTML(p, { size = '' } = {}) {
  return `
    <span class="intg-mark${size ? ` intg-mark--${size}` : ''}${WIDE_MARKS.has(p.slug) ? ' intg-mark--wide' : ''}">
      <img class="intg-logo" src="${esc(p.logo)}" alt="" loading="lazy"
           onerror="this.style.display='none';this.parentElement.querySelector('.intg-logo-fallback').style.display=''">
      <span class="material-symbols-outlined intg-logo-fallback" aria-hidden="true" style="display:none">${p.card.icon}</span>
    </span>`;
}

export function connFor(providersMap, slug) {
  const org = orgGuid();
  const conns = providersMap?.[slug] || [];
  return conns.find((c) => c.owner_guid === org) || conns[0] || null;
}

/** Uniform status derivation: unavailable | idle | connected | broken. */
export function statusOf(p, conn, configured) {
  // CallRail has no platform config gate (configured is always true server-side).
  if (p.connect && !configured) return 'unavailable';
  if (!conn) return 'idle';
  return conn.connect_status === 'ACTIVE' ? 'connected' : 'broken';
}

export function statusPill(status, conn) {
  if (status === 'unavailable') return `<span class="intg-state">Not available yet</span>`;
  if (status === 'idle') return `<span class="intg-state">Not connected</span>`;
  if (status === 'connected') return `<span class="intg-state on"><span class="material-symbols-outlined" aria-hidden="true">check</span>Connected</span>`;
  return `<span class="intg-state warn"><span class="material-symbols-outlined" aria-hidden="true">priority_high</span>${esc(conn?.connect_status === 'NEEDS_REAUTH' ? 'Reconnect needed' : 'Connection error')}</span>`;
}

/** GET /integrations for the active org. Returns {denied:true} on 403. */
export async function fetchIntegrations() {
  const res = await fetch(`${apiBase()}/m5t/v5/integrations`);
  if (res.status === 403) return { denied: true };
  const data = await res.json();
  if (!data.ok) throw new Error(data.error || 'load failed');
  return { providers: data.data.providers, configured: data.data.configured };
}

// ── actions (shared by hub + detail; `refresh` is the caller's reload) ───────
export async function connectProvider(p) {
  if (busyLock.busy) return;
  busyLock.busy = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/connect`);
    const data = await res.json();
    if (!data.ok || !data.data?.url) throw new Error(data.error || 'connect failed');
    window.location.href = data.data.url;
  } catch (e) {
    // Surface the REAL reason (e.g. "Google Ads is not configured on this
    // server") - the whole point of the shared body; see 0dcf1f4.
    toast(e.message || p.connect.fallbackError, 'error');
    busyLock.busy = false;
  }
}

export async function syncProvider(p, { refresh } = {}) {
  if (busyLock.busy) return;
  busyLock.busy = true;
  const btn = document.getElementById(p.card.ids.sync);
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/sync`, { method: 'POST' });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'sync failed');
    const items = data.data?.connections?.[0]?.[p.sync.itemsField] || [];
    const failed = items.filter((it) => it.error).length;
    toast(failed ? p.sync.failedToast(failed) : 'Metrics synced.', failed ? 'warning' : 'success');
  } catch (e) {
    toast('Sync failed.', 'error');
  } finally {
    busyLock.busy = false;
    if (btn) btn.disabled = false;
    refresh?.();
  }
}

export async function disconnectProvider(p, { refresh } = {}) {
  if (busyLock.busy) return;
  // Latch BEFORE awaiting the dialog: a second activation while it is open
  // must not stack a second confirm (and double-DELETE on both OKs).
  busyLock.busy = true;
  let ok = false;
  try {
    ok = await confirmDialog({
      title: `Disconnect ${p.label}?`,
      message: p.disconnect.confirm,
      confirmLabel: 'Disconnect',
      danger: true,
    });
  } finally {
    if (!ok) busyLock.busy = false;
  }
  if (!ok) return;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}`, { method: 'DELETE' });
    const data = await res.json().catch(() => ({}));
    if (!data.ok) throw new Error(data.error || 'disconnect failed');
    toast(p.disconnect.toast, 'success');
  } catch (e) {
    toast('Disconnect failed.', 'error');
  } finally {
    busyLock.busy = false;
    refresh?.();
  }
}

// ── sub-account picker (Google Ads accounts / GA4 properties) ────────────────
export async function openProviderPicker(p, { refresh } = {}) {
  const pk = p.picker;
  const panel = document.getElementById(p.card.ids.panel);
  if (!panel) return;
  panel.style.display = '';
  panel.innerHTML = alertHTML(pk.loading);
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/${pk.path}`);
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'load failed');
    renderProviderPicker(p, data.data[pk.itemsField] || [], new Set(data.data.linked || []), { refresh });
  } catch (e) {
    panel.innerHTML = alertHTML(pk.loadError, 'error');
  }
}

function renderProviderPicker(p, items, linked, { refresh } = {}) {
  const pk = p.picker;
  const panel = document.getElementById(p.card.ids.panel);
  if (!panel) return;

  const rows = items.map((it) => {
    const disabled = pk.rowDisabled(it);
    const badge = pk.rowBadge(it);
    const checked = linked.has(it.id) && !disabled;
    return `
      <label class="intg-acct${disabled ? ' disabled' : ''}">
        <input type="checkbox" data-${pk.dataAttr}="${esc(it.id)}" ${checked ? 'checked' : ''} ${disabled ? 'disabled' : ''}>
        <span style="min-width:0">
          <span class="intg-acct__name">${esc(it.name || pk.namePrefix + it.id)}</span>
          <div class="intg-acct__id">${esc(it.id)}</div>
        </span>
        ${badge ? `<span class="intg-acct__badge">${esc(badge)}</span>` : '<span></span>'}
      </label>`;
  }).join('');

  panel.innerHTML = `
    <div class="intg-picker">
      <div class="intg-picker__head">
        <span>${pk.heading}</span>
        <span style="font-weight:500">${items.filter((it) => !pk.rowDisabled(it)).length} selectable</span>
      </div>
      <div class="intg-picker__list">
        ${rows || `<div class="intg-picker__empty">${pk.emptyMsg}</div>`}
      </div>
      <div class="intg-picker__foot">
        <button type="button" class="intg-btn" id="${pk.ids.cancel}">Cancel</button>
        <button type="button" class="intg-btn primary" id="${pk.ids.save}"><span class="material-symbols-outlined" aria-hidden="true">save</span>Save</button>
      </div>
    </div>`;

  document.getElementById(pk.ids.cancel)?.addEventListener('click', () => { panel.style.display = 'none'; });
  document.getElementById(pk.ids.save)?.addEventListener('click', () => saveProviderPicker(p, { refresh }));
}

async function saveProviderPicker(p, { refresh } = {}) {
  const pk = p.picker;
  const panel = document.getElementById(p.card.ids.panel);
  const ids = [...(panel?.querySelectorAll(`input[data-${pk.dataAttr}]:checked`) || [])].map((el) => el.dataset[pk.datasetKey]);
  const btn = document.getElementById(pk.ids.save);
  if (btn) btn.disabled = true;
  try {
    const res = await fetch(`${apiBase()}/m5t/v5/integrations/${p.slug}/${pk.path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ [pk.saveField]: ids }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'save failed');
    toast(pk.savedToast(data.data.linked), 'success');
    if (panel) panel.style.display = 'none';
    refresh?.();
  } catch (e) {
    toast(pk.saveError, 'error');
    if (btn) btn.disabled = false;
  }
}

// ── CallRail: paste-key setup (no OAuth exists for their API) ────────────────
// HighLevel pasted-token connect: token + sub-account Location ID.
export function openGhlSetup({ refresh } = {}) {
  const panel = document.getElementById(PROVIDERS.gohighlevel.card.ids.setup);
  if (!panel) return;
  panel.style.display = '';
  panel.innerHTML = `
    <div class="intg-picker">
      <div class="intg-picker__head"><span>Connect HighLevel</span></div>
      <div class="intg-form">
        <div>
          <label for="intg-gh-token">Private integration token</label>
          <input class="intg-input" id="intg-gh-token" type="password" autocomplete="off" spellcheck="false" placeholder="pit-...">
          <p class="intg-hint">Create one in the sub-account under Settings, then Private Integrations, with the contacts.write scope.</p>
        </div>
        <div>
          <label for="intg-gh-location">Location ID</label>
          <input class="intg-input" id="intg-gh-location" type="text" autocomplete="off" spellcheck="false" placeholder="The sub-account Location ID">
          <p class="intg-hint">Copy it from the sub-account under Settings, then Business Profile.</p>
        </div>
        <p class="intg-hint" id="intg-gh-status" role="status"></p>
      </div>
      <div class="intg-picker__foot">
        <button type="button" class="intg-btn" id="intg-gh-cancel">Cancel</button>
        <button type="button" class="intg-btn primary" id="intg-gh-save">Connect</button>
      </div>
    </div>`;
  const status = (msg) => { const el = document.getElementById('intg-gh-status'); if (el) el.textContent = msg; };
  document.getElementById('intg-gh-cancel')?.addEventListener('click', () => { panel.style.display = 'none'; });
  document.getElementById('intg-gh-save')?.addEventListener('click', async () => {
    const btn = document.getElementById('intg-gh-save');
    const token = document.getElementById('intg-gh-token')?.value.trim() || '';
    const locationId = document.getElementById('intg-gh-location')?.value.trim() || '';
    if (!token || !locationId) { status('Paste the token and the Location ID first.'); return; }
    btn.disabled = true;
    status('Checking with HighLevel…');
    try {
      const res = await fetch(`${apiBase()}/m5t/v5/integrations/gohighlevel/connect`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, location_id: locationId }),
      });
      const data = await res.json().catch(() => ({}));
      if (!data.ok) throw new Error(data.error || 'Could not connect HighLevel.');
      toast(`HighLevel connected${data.data.location_name ? ` to ${data.data.location_name}` : ''}.`, 'success');
      panel.style.display = 'none';
      refresh?.();
    } catch (e) {
      status(e.message || 'Could not connect HighLevel.');
      btn.disabled = false;
    }
  });
  document.getElementById('intg-gh-token')?.focus();
}

