/**
 * ad-performance-route.js — client-saas /analytics/ad-performance
 *
 * The managed-client (and reseller-over-subtree) view of ad performance correlated to
 * magnet leads: ad spend / clicks on the same timeline as magnet leads, with Cost-Per-Lead.
 * Reads the owner-scoped GET /m5t/v5/coreAdMetrics/overlay (server does the day×tenant join)
 * and GET /m5t/v5/coreAdAccount (to distinguish "no account connected" from "no data yet").
 * Chart is a hand-rolled inline SVG (dual-axis: spend bars + leads line) — zero bundle cost
 * (the app builds a single inlined bundle, so a chart lib would bloat every page). Honest
 * empty-states — never fabricated numbers.
 */

import AuthController from '../services/AuthController.js';
import { inPortfolio, pickerPageHTML, initPicker } from '../services/portfolio-view.js';
import {
  PROVIDERS, connFor, statusOf, statusPill, fetchIntegrations,
  canManage, ensureStyles as ensureIntgStyles,
} from '../services/integrations-shared.js';
import { statCard } from '../core/statCard.js';
import { ensureChartStyles, dualAxisChartHTML, wireChartHover, fmtAxis } from '../services/chart-kit.js';
import { capList } from '../core/listExpand.js';
import { setHandoff, HANDOFF } from '../core/routeHandoff.js';

const apiBase = () => AuthController.getConfig?.().BASE_URL || '';
const ymd = (d) => d.toISOString().slice(0, 10);
const fmtMoney = (n) => (n == null ? '—' : '$' + Number(n).toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 2 }));
const fmtNum = (n) => Number(n || 0).toLocaleString();
const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ESC[c]); // UTM values come from URLs

let stylesInjected = false;
function ensureStyles() {
  ensureChartStyles();
  if (stylesInjected) return;
  const s = document.createElement('style');
  s.id = 'm5t-adperf-styles';
  s.textContent = `
    .page-shell .adperf-note { font-size: 0.76rem; color: var(--color-text-subtle, #6C7C9A); margin: 12px 2px 0; }
    .page-shell .chart-period-btn { cursor: pointer; }
    .page-shell .chart-period-btn.active { background: var(--color-primary-600, #0072BA); color: #fff; }
    .page-shell .adperf-srcwrap { overflow-x: auto; }
    .page-shell .adperf-srctable { width: 100%; border-collapse: collapse; font-size: 0.88rem; }
    .page-shell .adperf-srctable th { text-align: left; font-size: 0.68rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; color: var(--color-text-subtle, #6C7C9A); padding: 8px 12px; border-bottom: 1px solid var(--color-border, #D4DCE8); white-space: nowrap; }
    .page-shell .adperf-srctable td { padding: 9px 12px; border-bottom: 1px solid var(--color-surface-2, #EAF0F7); vertical-align: middle; }
    .page-shell .adperf-srctable .num { text-align: right; white-space: nowrap; }
    /* A row that drills through to /leads. Only rows with a campaign or source get this —
       the untracked/direct bucket has nothing to search for, so it stays inert and
       deliberately looks it. */
    .page-shell .adperf-srcrow--link { cursor: pointer; transition: background 0.12s ease; }
    .page-shell .adperf-srcrow--link:hover { background: var(--color-surface, #F4F7FB); }
    .page-shell .adperf-srclink { color: inherit; text-decoration: none; font-weight: 600; }
    .page-shell .adperf-srcrow--link:hover .adperf-srclink { color: var(--color-primary-600, #0072BA); text-decoration: underline; }
    /* Focus lands on the <a>, but the whole ROW is the hit target, so show the ring on
       the row — otherwise keyboard users get an outline round the text while the thing
       that responds to Enter is the row around it. */
    .page-shell .adperf-srcrow--link:focus-within { outline: 2px solid var(--color-primary-600, #0072BA); outline-offset: -2px; }
    html.ff-no-animations .page-shell .adperf-srcrow--link { transition: none; }
    @media (prefers-reduced-motion: reduce) { .page-shell .adperf-srcrow--link { transition: none; } }
    .page-shell .adperf-src-sub { font-size: 0.78rem; color: var(--color-text-subtle, #6C7C9A); }
    .page-shell .adperf-src-untracked { color: var(--color-text-subtle, #6C7C9A); font-style: italic; }
    .page-shell .adperf-conn { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-top: 8px; font-size: 0.8rem; font-weight: 600; color: var(--color-text-muted, #4A5A78); }
    .page-shell .adperf-conn:empty { display: none; }
    .page-shell .adperf-conn a { color: var(--color-accent, #0072BA); font-weight: 600; }
  `;
  document.head.appendChild(s);
  stylesInjected = true;
}

const emptyState = (icon, msg) =>
  `<div class="m5t-empty"><span class="material-symbols-outlined" aria-hidden="true">${icon}</span><p>${msg}</p></div>`;



const PERIODS = [{ d: 7, label: '7 Days' }, { d: 30, label: '30 Days' }, { d: 90, label: '90 Days' }];
let periodDays = 30;

export function render() {
  if (inPortfolio()) {
    return pickerPageHTML({
      section: 'ad-performance', title: 'Ad Performance',
      description: 'Pick a client to view their spend and lead performance.',
    });
  }
  ensureStyles();
  return `
    <div class="page-shell" data-section="ad-performance">
      <div class="page-header">
        <div class="page-header-text">
          <h1 class="page-title">Ad Performance</h1>
          <p class="page-description">Your advertising spend alongside the leads your magnets captured.</p>
          <div class="adperf-conn" id="adperf-conn"></div>
        </div>
        <div class="chart-controls" id="adperf-periods">
          ${PERIODS.map((p) => `<button class="chart-period-btn${p.d === periodDays ? ' active' : ''}" type="button" data-days="${p.d}">${p.label}</button>`).join('')}
        </div>
      </div>

      <div class="stats-grid" id="adperf-stats">
        ${statCard({ icon: 'payments', label: 'Ad Spend', valueId: 'adperf-spend', href: '#/ad-accounts' })}
        ${statCard({ icon: 'ads_click', label: 'Clicks', valueId: 'adperf-clicks', href: '#/ad-accounts' })}
        ${statCard({ icon: 'person_add', label: 'Magnet Leads', valueId: 'adperf-leads', href: '#/leads' })}
        ${statCard({ icon: 'request_quote', label: 'Cost / Lead', valueId: 'adperf-cpl' })}
      </div>

      <div class="dashboard-card">
        <div class="card-header">
          <h2 class="card-title"><span class="material-symbols-outlined" aria-hidden="true">insights</span> Spend vs Leads</h2>
          <span class="live-indicator" id="adperf-range"></span>
        </div>
        <div class="card-body" id="adperf-body">
          ${emptyState('hourglass_empty', 'Loading ad performance…')}
        </div>
      </div>
      <p class="adperf-note">Spend and leads are shown on the same timeline for comparison. Leads are not yet matched to individual ad clicks.</p>

      <div class="dashboard-card">
        <div class="card-header">
          <h2 class="card-title"><span class="material-symbols-outlined" aria-hidden="true">campaign</span> Leads by campaign</h2>
          <span class="live-indicator" id="adperf-src-summary"></span>
        </div>
        <div class="card-body" id="adperf-sources">
          ${emptyState('hourglass_empty', 'Loading…')}
        </div>
      </div>

      <div class="dashboard-card" id="adperf-conv-card" style="display:none">
        <div class="card-header">
          <h2 class="card-title"><span class="material-symbols-outlined" aria-hidden="true">flag</span> Other conversions</h2>
          <span class="live-indicator">Reported by Google Ads</span>
        </div>
        <div class="card-body" id="adperf-conv-body"></div>
      </div>

      <div class="dashboard-card" id="adperf-lsa-card" style="display:none">
        <div class="card-header">
          <h2 class="card-title"><span class="material-symbols-outlined" aria-hidden="true">home_repair_service</span> Local Services</h2>
          <span class="live-indicator">Reported by Google</span>
        </div>
        <div class="card-body" id="adperf-lsa-body"></div>
      </div>
    </div>`;
}

export async function init() {
  if (inPortfolio()) {
    const fmtN = (n) => Number(n || 0).toLocaleString();
    return initPicker(apiBase(), [
      { h: 'Spend', td: (r) => (r.ad ? `$${fmtN(r.ad.spend)}` : '—') },
      { h: 'Clicks', td: (r) => (r.ad ? fmtN(r.ad.clicks) : '—') },
      { h: 'Leads', td: (r) => fmtN(r.leads.window ?? r.leads.total) },
      { h: 'CPL', td: (r) => (r.ad?.cost_per_lead != null ? `$${fmtN(r.ad.cost_per_lead)}` : '—') },
    ], { emptyMsg: 'No client orgs yet. Connect a client ad account to see spend here.' });
  }
  const periods = document.getElementById('adperf-periods');
  periods?.addEventListener('click', (e) => {
    const btn = e.target.closest('button[data-days]');
    if (!btn) return;
    periodDays = Number(btn.dataset.days) || 30;
    periods.querySelectorAll('.chart-period-btn').forEach((b) => b.classList.toggle('active', Number(b.dataset.days) === periodDays));
    load();
  });

  // Campaign drill-through, delegated on the stable container rather than the rows:
  // renderSources() replaces this card's innerHTML on every period change and capList()
  // re-renders it again on expand, so per-row listeners would be dropped each time. Same
  // reasoning, and the same routeHandoff mechanism, as the dashboard's campaign list —
  // NOT a second filtering path. /leads claims LEADS_SEARCH and resets its own status
  // filters, because a drill-through is a fresh question.
  document.getElementById('adperf-sources')?.addEventListener('click', (e) => {
    const row = e.target.closest('tr[data-campaign]');
    if (!row) return;
    setHandoff(HANDOFF.LEADS_SEARCH, row.dataset.campaign);
    // The <a> in the first cell navigates natively — it exists so the row keyboard-
    // focuses and middle-clicks like a link, which a click-only <tr> cannot. For a click
    // anywhere ELSE in the row, this drives the same navigation so the whole row is
    // clickable, which is what the table reads as.
    if (e.target.closest('a')) return;
    window.location.hash = '#/leads';
  });

  // LSA lead drill-through — same delegated pattern (the card re-renders per
  // period change). Search term = the lead's phone (in the leads search hay),
  // falling back to the name.
  document.getElementById('adperf-lsa-card')?.addEventListener('click', (e) => {
    const row = e.target.closest('tr[data-lsalead]');
    if (!row) return;
    setHandoff(HANDOFF.LEADS_SEARCH, row.dataset.lsalead);
    if (e.target.closest('a')) return;
    window.location.hash = '#/leads';
  });

  await load();
}

async function load() {
  const base = apiBase();
  const body = document.getElementById('adperf-body');
  const rangeEl = document.getElementById('adperf-range');
  const now = new Date();
  const to = ymd(now);
  const from = ymd(new Date(now.getTime() - (periodDays - 1) * 86400000));
  if (rangeEl) rangeEl.textContent = `${from} → ${to}`;

  let overlay, accounts = [], sources = null, intg = null, conv = null, lsa = null;
  try {
    const [oRes, aRes, sRes, intgRes, cRes, lsaRes] = await Promise.all([
      fetch(`${base}/m5t/v5/coreAdMetrics/overlay?from=${from}&to=${to}`),
      fetch(`${base}/m5t/v5/coreAdAccount`),
      fetch(`${base}/m5t/v5/coreAdMetrics/by-source?from=${from}&to=${to}`),
      fetchIntegrations().catch(() => null), // notation only — never blocks the page
      fetch(`${base}/m5t/v5/coreAdMetrics/conversions?from=${from}&to=${to}`).then((r) => r.json()).catch(() => null),
      fetch(`${base}/m5t/v5/coreAdMetrics/lsa?from=${from}&to=${to}`).then((r) => r.json()).catch(() => null),
    ]);
    if (!oRes.ok) throw new Error(`HTTP ${oRes.status}`);
    overlay = await oRes.json();
    const aJson = await aRes.json().catch(() => ({}));
    accounts = (aJson?.data || []).filter((a) => a.status !== 'DELETED');
    sources = await sRes.json().catch(() => null);
    intg = intgRes;
    conv = cRes;
    lsa = lsaRes;
  } catch (err) {
    console.warn('[ad-performance] load failed:', err);
    if (body) body.innerHTML = emptyState('error', 'Could not load ad performance. Please try again.');
    return;
  }

  renderConnNote(intg, accounts);
  renderConversions(conv, overlay?.totals?.spend ?? null);
  renderLsa(lsa);

  const t = overlay.totals || {};
  setText('adperf-spend', fmtMoney(t.spend));
  setText('adperf-clicks', fmtNum(t.clicks));
  setText('adperf-leads', fmtNum(t.magnet_leads));
  setText('adperf-cpl', fmtMoney(t.cost_per_lead));

  // Leads-by-campaign renders from captured UTM regardless of a connected ad account.
  renderSources(sources);

  if (!accounts.length) {
    body.innerHTML = emptyState('link_off', 'No ad account connected yet. Your agency can connect Google Ads or Local Services Ads to see performance here.');
    return;
  }
  if (!overlay.connected) {
    body.innerHTML = emptyState('cloud_sync', 'Account connected. No ad data for this range yet. Metrics appear here once they sync.');
    return;
  }

  // Render the dual-axis overlay chart (inline SVG).
  const overlayRows = overlay.rows || [];
  body.innerHTML = svgOverlayChart(overlayRows);
  wireSpendChart(overlayRows);
}

/**
 * Header notation: where this page's ad data comes from. The Google Ads OAuth
 * connection state uses the same derivation as Settings → Integrations
 * (connFor/statusOf/statusPill); with no OAuth link, associated Customer IDs
 * (coreAdAccount, agency-managed) are the source and get a neutral count.
 * Silent when neither exists — the chart empty states already explain that.
 */
function renderConnNote(intg, accounts) {
  const host = document.getElementById('adperf-conn');
  if (!host) return;
  if (!intg || intg.denied) { host.innerHTML = ''; return; }
  const p = PROVIDERS.google_ads;
  const conn = connFor(intg.providers, 'google_ads');
  const status = statusOf(p, conn, !!intg.configured?.google_ads);
  const manage = canManage()
    ? ` <a href="#/settings/integrations/${p.urlSlug}">Manage</a>` : '';
  if (status === 'connected' || status === 'broken') {
    ensureIntgStyles(); // .intg-state pill styles, shared with Settings
    host.innerHTML = `<span>Google Ads</span> ${statusPill(status, conn)}${manage}`;
    return;
  }
  if (accounts.length) {
    host.innerHTML = `<span>Google Ads</span> <span>${accounts.length} associated account${accounts.length === 1 ? '' : 's'}</span>`;
    return;
  }
  host.innerHTML = '';
}

/**
 * "Other conversions": the reseller-selected Google Ads conversion actions
 * (GET /coreAdMetrics/conversions). Opt-in — nothing renders until actions are
 * chosen on the Google Ads integration page. Deliberately a SEPARATE stream:
 * these are Google's platform-reported numbers, never summed with magnet leads
 * (a lead that also fires a gtag conversion would double-count), so the stat
 * card and table carry their own provenance label instead of blending in.
 */
function renderConversions(conv, spendTotal) {
  const card = document.getElementById('adperf-conv-card');
  const bodyEl = document.getElementById('adperf-conv-body');
  const grid = document.getElementById('adperf-stats');
  const oldStat = document.getElementById('adperf-conv-stat');
  if (oldStat) oldStat.remove();
  const oldCpc = document.getElementById('adperf-conv-cpc');
  if (oldCpc) oldCpc.remove();
  if (!card || !bodyEl) return;
  if (!conv?.ok || !conv.has_selection) { card.style.display = 'none'; return; }

  // Fifth stat card, provenance in the sublabel.
  if (grid) {
    // Through the shared helper, rather than hand-writing this markup a fourth time. It is
    // appended after load (the card only exists when Google Ads reports conversions), so
    // the HTML is parsed in a throwaway wrapper and the card element moved across.
    const holder = document.createElement('div');
    holder.innerHTML = statCard({
      icon: 'flag',
      label: 'Ads Conversions',
      value: fmtNum(conv.totals?.conversions),
      sub: 'Reported by Google Ads',
      // Which actions are counted is chosen on the integration page the sublabel names.
      href: '#/settings/integrations/google-ads',
    });
    const stat = holder.firstElementChild;
    stat.id = 'adperf-conv-stat';
    grid.appendChild(stat);

    // Cost per conversion, beside the count it derives from. Deliberately NOT next to
    // Cost / Lead: that one divides by magnet leads, this one by Google's attributed
    // conversions, and the two denominators must not read as interchangeable. Null (the
    // em-dash placeholder) whenever the division has no meaning — no conversions in the
    // range means there is no cost per conversion, and "$0" would be a claim.
    const conversions = Number(conv.totals?.conversions || 0);
    const cpc = (spendTotal != null && conversions > 0)
      ? Math.round((Number(spendTotal) / conversions) * 100) / 100 : null;
    const cpcHolder = document.createElement('div');
    cpcHolder.innerHTML = statCard({
      icon: 'request_quote',
      label: 'Cost / Conversion',
      value: fmtMoney(cpc),
      sub: 'Against the counted actions',
      // The full report, where the counted actions can be changed and everything
      // recomputes against the new selection.
      href: '#/analytics/conversions',
    });
    const cpcStat = cpcHolder.firstElementChild;
    cpcStat.id = 'adperf-conv-cpc';
    grid.appendChild(cpcStat);
  }

  const actions = conv.actions || [];
  card.style.display = '';
  if (!actions.length) {
    bodyEl.innerHTML = emptyState('search_off', 'No conversions in this range for the selected actions.');
    return;
  }
  const showValue = actions.some((a) => a.value > 0);
  bodyEl.innerHTML = `
    <div class="adperf-srcwrap">
      <table class="adperf-srctable">
        <thead><tr><th>Conversion action</th><th>Category</th><th class="num">Conversions</th>${showValue ? '<th class="num">Value</th>' : ''}</tr></thead>
        <tbody>${actions.map((a) => `
          <tr>
            <td>${esc(a.name || a.id)}</td>
            <td class="adperf-src-sub">${esc(String(a.category || '').toLowerCase().replace(/_/g, ' ') || '—')}</td>
            <td class="num"><b>${fmtNum(a.conversions)}</b></td>
            ${showValue ? `<td class="num">${fmtMoney(a.value)}</td>` : ''}
          </tr>`).join('')}
        </tbody>
      </table>
    </div>
    <p class="adperf-note">Counted actions are chosen on the Google Ads integration page. These are Google's own numbers and may overlap magnet leads, so they are never added together.</p>`;
}

/**
 * Local Services Ads (GET /coreAdMetrics/lsa) — its OWN section, never blended
 * into the overlay: LSA has no landing pages, so these leads cannot tie to
 * magnets and the numbers are Google's own. Hidden entirely until a linked
 * account shows LSA activity, so non-LSA accounts never see the card.
 */
function renderLsa(data) {
  const card = document.getElementById('adperf-lsa-card');
  const bodyEl = document.getElementById('adperf-lsa-body');
  if (!card || !bodyEl) return;
  if (!data?.ok || !data.connected) { card.style.display = 'none'; return; }
  card.style.display = '';

  const t = data.totals || {};
  const leads = data.leads || [];
  const disputes = data.disputes || [];
  // Answer rate is the coaching lever: LSA ranking punishes unanswered calls.
  // Null when no call outcome is known for the range (never a fake 100%).
  const answerSub = t.answer_rate == null ? 'No call outcomes yet'
    : t.missed > 0 ? `${fmtNum(t.missed)} missed call${t.missed === 1 ? '' : 's'}` : 'Every call answered';
  const kpis = `
    <div class="stats-grid" style="margin-bottom:16px">
      ${statCard({ icon: 'payments', label: 'LSA Spend', value: fmtMoney(t.spend), sub: 'Reported by Google' })}
      ${statCard({ icon: 'person_add', label: 'LSA Leads', value: fmtNum(t.leads), sub: `${fmtNum(t.phone_calls)} calls · ${fmtNum(t.messages)} messages` })}
      ${statCard({ icon: 'paid', label: 'Charged', value: fmtNum(t.charged), sub: 'Leads Google billed for' })}
      ${statCard({ icon: 'request_quote', label: 'Cost / Charged Lead', value: fmtMoney(t.cost_per_charged_lead) })}
      ${statCard({ icon: 'call', label: 'Answer Rate', value: t.answer_rate == null ? '—' : `${t.answer_rate}%`, sub: answerSub })}
      ${statCard({ icon: 'event_available', label: 'Booked', value: fmtNum(t.booked), sub: "Google's lead status" })}
    </div>`;

  const table = leads.length ? `
    <div class="adperf-srcwrap">
      <table class="adperf-srctable">
        <thead><tr><th>Lead</th><th>Contact</th><th>Type</th><th>Category</th><th>Google status</th><th class="num">Charged</th><th>Received</th></tr></thead>
        <tbody>${leads.map((l) => {
    const term = l.phone || l.name;
    const when = l.captured_at ? new Date(l.captured_at).toLocaleDateString([], { month: 'short', day: 'numeric' }) : '—';
    return `
          <tr${term ? ` data-lsalead="${esc(term)}" class="adperf-srcrow--link"` : ''}>
            <td>${term ? `<a class="adperf-srclink" href="#/leads" title="Open this lead">${esc(l.name)}</a>` : esc(l.name)}</td>
            <td class="adperf-src-sub">${esc([l.phone, l.email].filter(Boolean).join(' · ') || '—')}</td>
            <td>${esc(l.type || '—')}${l.missed ? ' <span class="adperf-src-untracked">· missed</span>' : ''}</td>
            <td class="adperf-src-sub">${esc(l.category || '—')}</td>
            <td class="adperf-src-sub">${esc(String(l.lsa_status || '—').toLowerCase())}${l.dispute ? ' <span class="adperf-src-untracked">· dispute candidate</span>' : ''}</td>
            <td class="num">${l.charged ? '<b>yes</b>' : '<span class="adperf-src-sub">no</span>'}</td>
            <td class="adperf-src-sub">${esc(when)}</td>
          </tr>`;
  }).join('')}
        </tbody>
      </table>
    </div>`
    : emptyState('search_off', 'No Local Services leads in this range yet.');

  // Dispute hygiene: charged leads Google's own signals mark dispute-worthy,
  // while the 30-day credit window is still open. Filing happens on Google's
  // side — this list is the reminder with the countdown.
  const disputeBlock = disputes.length ? `
    <div class="card-header" style="padding:16px 0 0">
      <h3 class="card-title" style="font-size:1rem"><span class="material-symbols-outlined" aria-hidden="true">flag_circle</span> Dispute candidates</h3>
      <span class="live-indicator">${fmtNum(disputes.length)} inside the 30 day credit window</span>
    </div>
    <div class="adperf-srcwrap">
      <table class="adperf-srctable">
        <thead><tr><th>Lead</th><th>Why</th><th class="num">Days left</th></tr></thead>
        <tbody>${disputes.map((d) => `
          <tr>
            <td>${esc(d.name)}${d.phone ? ` <span class="adperf-src-sub">${esc(d.phone)}</span>` : ''}</td>
            <td class="adperf-src-sub">${esc(d.reason)}</td>
            <td class="num"><b>${fmtNum(d.days_left)}</b></td>
          </tr>`).join('')}
        </tbody>
      </table>
    </div>
    <p class="adperf-note">These charged leads look credit-eligible. Review and dispute them in <a href="https://ads.google.com/localservices/leads" target="_blank" rel="noopener">your Google Local Services lead inbox</a> before the window closes.</p>` : '';

  bodyEl.innerHTML = `
    ${kpis}
    ${table}
    ${disputeBlock}
    <p class="adperf-note">Numbers come from Google's Local Services feed. These leads land in your Leads inbox and do not flow through magnets.</p>`;

  const tb = bodyEl.querySelector('.adperf-srctable tbody');
  if (tb) capList(tb, { rowSelector: 'tr', noun: 'leads', controlHost: bodyEl.querySelector('.adperf-srcwrap') || bodyEl });
}

// Leads grouped by campaign/source (GET /coreAdMetrics/by-source) — a simple ranked table.
function renderSources(data) {
  const host = document.getElementById('adperf-sources');
  const sum = document.getElementById('adperf-src-summary');
  if (!host) return;
  const rows = (data && Array.isArray(data.rows)) ? data.rows : [];
  if (!rows.length) {
    if (sum) sum.textContent = '';
    host.innerHTML = emptyState('search_off', 'No leads in this range yet. Campaigns appear here as tagged leads (?utm_campaign=…) come in.');
    return;
  }
  const total = data.total_leads || rows.reduce((a, r) => a + (r.leads || 0), 0);
  const tracked = data.tracked_leads || 0;
  if (sum) sum.textContent = `${fmtNum(tracked)} of ${fmtNum(total)} leads tagged to a source`;
  const label = (r) => {
    if (r.campaign && r.campaign !== '(none)') return esc(r.campaign);
    if (r.source && r.source !== '(direct)') return esc(r.source);
    return '<span class="adperf-src-untracked">Untracked / direct</span>';
  };
  // What /leads should search for when this row is clicked: the campaign if there is a
  // real one, otherwise the source. Returns '' for the untracked/direct bucket, which
  // deliberately makes that row NOT clickable — it is the rows that carry no campaign and
  // no source, so there is nothing to search for and a drill-through would land on a
  // filtered-to-nothing leads list. Same precedence as label() above, so the row searches
  // for the thing it is displaying.
  const searchFor = (r) => {
    if (r.campaign && r.campaign !== '(none)') return r.campaign;
    if (r.source && r.source !== '(direct)') return r.source;
    return '';
  };
  host.innerHTML = `
    <div class="adperf-srcwrap">
      <table class="adperf-srctable">
        <thead><tr><th>Campaign</th><th>Source</th><th class="num">Paid clicks</th><th class="num">Leads</th></tr></thead>
        <tbody>${rows.map((r) => {
    const term = searchFor(r);
    // data-campaign carries the RAW value; esc() is for the attribute and the handler
    // reads the decoded value back off the dataset — same contract as the dashboard's
    // campaign rows.
    return `
          <tr${term ? ` data-campaign="${esc(term)}" class="adperf-srcrow--link"` : ''}>
            <td>${term
      ? `<a class="adperf-srclink" href="#/leads" title="Show the leads from ${esc(term)}">${label(r)}</a>`
      : label(r)}</td>
            <td class="adperf-src-sub">${esc(r.source || '—')}${r.medium ? ` · ${esc(r.medium)}` : ''}</td>
            <td class="num">${r.paid_clicks ? fmtNum(r.paid_clicks) : '<span class="adperf-src-sub">—</span>'}</td>
            <td class="num"><b>${fmtNum(r.leads)}</b></td>
          </tr>`;
  }).join('')}
        </tbody>
      </table>
    </div>`;
  const srcTb = host.querySelector('.adperf-srctable tbody');
  if (srcTb) capList(srcTb, { rowSelector: 'tr', noun: 'sources', controlHost: host.querySelector('.adperf-srcwrap') || host });
}

function setText(id, v) { const el = document.getElementById(id); if (el) el.textContent = v; }

// Spend (bars, left axis) vs magnet leads (line, right axis), through the shared kit.
//
// This was a near-clone of the dashboard's trend chart with two real defects. Every mark
// carried a literal hex — #EAF0F7 grid, #0072BA bars, #009473 line/dots, plus two inline
// legend swatches — which are the LIGHT theme's values, so the whole chart stayed
// light-mode coloured against a dark background. And its only tooltips were native
// <title> elements: slow to appear, one value at a time, and nothing on touch — the exact
// mechanism the dashboard had already removed for those reasons.
//
// Both fall out of using the kit: colours come from --chart-* tokens via classes, and it
// gets the same hover, focus, keyboard and crosshair behaviour as the dashboard.
function svgOverlayChart(rows) {
  return dualAxisChartHTML({
    rows,
    xLabel: (r) => String(r.date || '').slice(5),
    left: { value: (r) => r.spend || 0, label: 'Ad Spend', fmt: (v) => `$${fmtAxis(v)}` },
    right: { value: (r) => r.magnet_leads || 0, label: 'Magnet Leads' },
    ariaLabel: 'Ad spend versus magnet leads over time',
    pointLabel: (r) => `${r.date}: ${fmtMoney(r.spend || 0)} spend, ${fmtNum(r.magnet_leads || 0)} leads`,
    hitData: (r) => ({ day: r.date }),
  });
}

/** Wire the spend chart's tooltip/keyboard behaviour. No drill-through: there is no
 *  per-day ad-spend view to land on, so the chart informs rather than navigates. */
function wireSpendChart(rows) {
  const host = document.getElementById('adperf-body');
  if (!host) return () => {};
  return wireChartHover(host, {
    rows,
    tipHTML: (r) => `
      <div class="m5c-tip__title">${esc(String(r.date || ''))}</div>
      <div class="m5c-tip__row"><i class="m5c-sw m5c-sw--1"></i>${fmtMoney(r.spend || 0)} spend</div>
      <div class="m5c-tip__row"><i class="m5c-sw m5c-sw--2"></i>${fmtNum(r.magnet_leads || 0)} leads</div>`,
  });
}

export default { render, init };
